#include <LVRS/HierarchyController.h>
#include <iostream>
#include <thread>
using namespace ii;
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class T>T take(core::Result<T> r){if(!r){if(r.error().cause)std::rethrow_exception(r.error().cause);throw std::runtime_error(r.error().message);}return std::move(*r);}
void good(core::Result<void> r){if(!r)throw std::runtime_error(r.error().message);}
struct Fixture final {
    std::shared_ptr<lvrs::HierarchyModel> model=take(lvrs::HierarchyModel::create());
    std::shared_ptr<lvrs::HierarchyController> view;
    Fixture(bool automatic=true,bool editable=false){take(model->set_rows({{.key="root",.label="Root",.item_id=1,.expanded=true},{.key="branch",.label="Branch",.item_id=2,.depth=1},{.key="leaf",.label="Leaf",.item_id=3,.depth=2},{.key="disabled",.label="Disabled",.item_id=4,.depth=1,.enabled=false},{.key="other",.label="Other",.item_id=5}}));view=take(lvrs::HierarchyController::create(model,{.auto_expand_ancestors=automatic,.editable=editable}));}
};
void defaults(){Fixture f;auto state=take(f.view->state());check(state.active_key=="root"&&state.active_id==1&&state.count==5&&state.visible_count==4&&state.eligible_count==3&&!state.editable,"Initial hierarchy state or default activation differs");}
void activation(){Fixture f;const auto revision=take(f.model->state()).revision;check(take(f.view->activate_by_key("  leaf\t"))&&take(f.view->state()).active_id==3&&take(f.view->expanded("branch")),"Activation did not expand the selected row's ancestors");check(!take(f.view->activate_by_id(4))&&take(f.view->state()).active_key=="leaf"&&!take(f.view->activate_by_key("missing")),"An ineligible or absent row replaced activation");check(take(f.model->state()).revision==revision,"Activation changed source data");}
void hidden(){Fixture f(false);check(!take(f.view->activate_by_key("leaf"))&&take(f.view->state()).active_key=="root"&&!take(f.view->expanded("branch")),"Disabled ancestor expansion activated a hidden row");}
void keyboard(){Fixture f;take(f.view->navigate_right());check(take(f.view->state()).active_key=="branch","Right did not select the first child");take(f.view->navigate_right());check(take(f.view->expanded("branch"))&&take(f.view->state()).active_key=="branch","Right did not expand before descending");take(f.view->navigate_right());check(take(f.view->state()).active_key=="leaf","Right did not descend after expansion");take(f.view->navigate_left());check(take(f.view->state()).active_key=="branch","Left did not select the parent");take(f.view->navigate_left());check(!take(f.view->expanded("branch")),"Left did not collapse an expanded branch");take(f.view->activate_relative(1));check(take(f.view->state()).active_key=="other","Down did not skip a disabled row");}
void collapse(){Fixture f;take(f.view->activate_by_key("leaf"));take(f.view->set_expanded("branch",false));check(take(f.view->state()).active_key=="branch"&&!take(f.view->expanded("branch")),"Collapsing the active descendant did not activate its parent");take(f.view->collapse_all(false));check(take(f.view->state()).visible_count==2&&take(f.view->state()).active_key=="root","Collapse all did not preserve a visible active row");take(f.view->expand_all());check(take(f.view->state()).visible_count==5,"Expand all lost a row");}
void independent(){Fixture f;auto other=take(lvrs::HierarchyController::create(f.model));take(f.view->activate_by_key("leaf"));check(take(other->state()).active_key=="root"&&!take(other->expanded("branch")),"Two controllers shared view-local activation or expansion");}
void updates(){Fixture f;take(f.view->activate_by_key("branch"));auto row=take(f.model->row("branch")).get();row.label="Renamed";take(f.model->update_row("branch",row));check(take(f.view->state()).active_key=="branch"&&take(f.view->row(1)).label=="Renamed","Data update lost stable activation or label");row.enabled=false;take(f.model->update_row("branch",row));check(take(f.view->state()).active_key=="root","Disabling the active row left stale activation");take(f.model->set_rows({{.key="new",.label="New",.item_id=7}}));check(take(f.view->state()).active_id==7&&take(f.view->state()).count==1,"Reset did not normalize a removed key");}
void selected(){auto model=take(lvrs::HierarchyModel::create());take(model->set_rows({{.key="r",.label="Root"},{.key="s",.label="Selected",.depth=1,.selected=true}}));auto c=take(lvrs::HierarchyController::create(model));check(take(c->state()).active_key=="s"&&take(c->expanded("r")),"An initially selected hidden row did not open its ancestors");}
void force(){Fixture f;int active=0;auto port=std::make_shared<lvrs::HierarchyControllerPort>([&](const auto& e){active+=e.activation;});good(f.view->observe(port));const auto revision=take(f.view->state()).revision;check(!take(f.view->activate_by_key("root"))&&active==0&&take(f.view->state()).revision==revision,"Repeated activation was not inert");check(take(f.view->activate_by_key("root",true))&&active==1,"Forced activation did not publish exactly once");}
void extent(){Fixture f;const auto revision=take(f.model->state()).revision;take(f.view->set_row_extent("root",40));check(take(f.view->offset(1))==40&&take(f.view->at_offset(41))==1&&take(f.model->state()).revision==revision,"View-local height changed data or broke the height index");}
void drag(){Fixture f(true,true);const auto revision=take(f.model->state()).revision;check(take(f.view->begin_drag("branch"))&&take(f.view->update_drag(5,0)),"A valid subtree drag was not previewed");check(take(f.view->state()).dragging&&take(f.model->state()).revision==revision,"Drag preview changed source rows");take(f.view->end_drag(false));check(!take(f.view->state()).dragging&&take(f.model->state()).revision==revision,"Drag cancellation changed data");take(f.view->begin_drag("branch"));take(f.view->update_drag(5,0));take(f.view->end_drag(true));check(take(f.model->state()).revision==revision+1&&take(f.model->row(3)).get().key=="branch"&&take(f.model->row(4)).get().key=="leaf","Drag commit did not move the complete subtree once");}
void readonly(){Fixture f;check(!take(f.view->begin_drag("branch"))&&!take(f.view->move("branch",5,0)),"Read-only presentation admitted a move");take(f.view->set_editable(true));take(f.model->set_editable(false));check(!take(f.view->state()).editable&&!take(f.view->begin_drag("branch")),"Source editing capabilities were ignored");}
void stale(){Fixture f(true,true);take(f.view->begin_drag("branch"));take(f.view->update_drag(5,0));auto row=take(f.model->row("other")).get();row.label="Changed";take(f.model->update_row("other",row));check(!take(f.view->state()).dragging&&!take(f.view->end_drag(true)),"A source change left a stale drag plan committable");}
void observation(){Fixture f;bool blocked=false;auto port=std::make_shared<lvrs::HierarchyControllerPort>([&](const auto& e){check(take(f.view->state()).revision==e.state.revision,"An observer saw stale controller state");auto r=f.view->activate_by_key("other");blocked=!r&&r.error().code==core::ErrorCode::busy;});good(f.view->observe(port));take(f.view->activate_by_key("branch"));check(blocked&&take(f.view->state()).active_key=="branch","Controller notification admitted recursive mutation");}
void errors(){Fixture f;int next=0;auto bad=std::make_shared<lvrs::HierarchyControllerPort>([](const auto&){throw std::runtime_error("hierarchy receiver");});auto good_port=std::make_shared<lvrs::HierarchyControllerPort>([&](const auto&){++next;});good(f.view->observe(bad));good(f.view->observe(good_port));auto r=f.view->activate_by_key("branch");check(!r&&r.error().cause&&next==1&&take(f.view->state()).active_key=="branch","Observer failure rolled back activation or stopped fanout");}
void close(){Fixture f;good(f.view->close());check(take(f.view->state()).closed&&!f.view->activate_by_key("root")&&!take(f.model->state()).closed,"View closure damaged a shared model or accepted new commands");}
void source_close(){Fixture f;good(f.model->close());check(take(f.view->state()).closed&&take(f.view->state()).count==0,"Source closure left controller rows alive");}
void ownership(){Fixture f;bool blocked=false;std::thread worker([&]{auto r=f.view->state();blocked=!r&&r.error().code==core::ErrorCode::wrong_executor;});worker.join();check(blocked,"Controller accepted another thread");}
void default_extent(){Fixture f;take(f.view->set_row_extent("root",40));const auto revision=take(f.model->state()).revision;take(f.view->set_default_row_extent(17));check(take(f.view->row_extent(0))==40&&take(f.view->row_extent(1))==17&&take(f.view->state()).content_extent==91&&take(f.model->state()).revision==revision,"Default height replaced an explicit override or mutated source data");}
void cancel_notification(){Fixture f(true,true);bool requested=false;auto port=std::make_shared<lvrs::HierarchyControllerPort>([&](const auto& e){if(e.state.dragging&&!requested){requested=true;take(f.view->end_drag(false));}});good(f.view->observe(port));const auto revision=take(f.model->state()).revision;take(f.view->begin_drag("branch"));check(requested&&!take(f.view->state()).dragging&&take(f.model->state()).revision==revision,"Lifecycle cancellation was lost inside a drag notification");}

void pending_source(){Fixture f;bool updated=false;int calls=0;auto port=std::make_shared<lvrs::HierarchyControllerPort>([&](const auto&){++calls;if(!updated){updated=true;auto row=take(f.model->row("other")).get();row.label="From observer";take(f.model->update_row("other",row));}});good(f.view->observe(port));take(f.view->activate_by_key("branch"));check(updated&&calls==2&&take(f.view->state()).model_revision==take(f.model->state()).revision&&take(f.view->row(4)).label=="From observer","A source update during notification left the controller stale or permanently busy");}
void close_in_notify(){Fixture f;bool closed=false;auto port=std::make_shared<lvrs::HierarchyControllerPort>([&](const auto&){if(!closed){closed=true;good(f.model->close());}});good(f.view->observe(port));take(f.view->activate_by_key("branch"));check(closed&&take(f.view->state()).closed&&take(f.view->state()).count==0,"Source closure during notification did not finish controller retirement");}

void expansion_batch(){Fixture f;take(f.view->collapse_all(false));std::vector<lvrs::HierarchyControllerChange> events;auto port=std::make_shared<lvrs::HierarchyControllerPort>([&](const auto& e){events.push_back(e);});good(f.view->observe(port));const auto revision=take(f.model->state()).revision;take(f.view->expand_all());check(events.size()==1&&events[0].expansions==std::vector<lvrs::HierarchyExpansionChange>{{"root",0,true},{"branch",1,true}}&&events[0].state.visible_count==5&&events[0].key=="branch"&&events[0].expanded==true,"Bulk expansion lost transitions, preorder or final state");check(!take(f.view->expand_all())&&events.size()==1,"An unchanged bulk expansion emitted duplicate transitions");take(f.view->collapse_all(false));check(events.size()==2&&events[1].expansions==std::vector<lvrs::HierarchyExpansionChange>{{"root",0,false},{"branch",1,false}}&&take(f.model->state()).revision==revision,"Bulk collapse lost transitions or changed source data");}
void ancestor_events(){Fixture f;take(f.view->collapse_all(false));lvrs::HierarchyControllerChange event;int calls=0;auto port=std::make_shared<lvrs::HierarchyControllerPort>([&](const auto& e){event=e;++calls;});good(f.view->observe(port));take(f.view->activate_by_key("leaf"));check(calls==1&&event.activation&&event.expansions==std::vector<lvrs::HierarchyExpansionChange>{{"branch",1,true},{"root",0,true}}&&event.state.active_key=="leaf"&&event.state.visible_count==5,"Automatic ancestor expansion lost nearest-parent order or settled activation");take(f.view->set_expanded("branch",false));check(calls==2&&event.activation&&event.expansions==std::vector<lvrs::HierarchyExpansionChange>{{"branch",1,false}}&&event.state.active_key=="branch","Collapse activation did not retain the expansion record");}
void expansion_source(){Fixture f;std::vector<lvrs::HierarchyControllerChange> events;auto port=std::make_shared<lvrs::HierarchyControllerPort>([&](const auto& e){events.push_back(e);});good(f.view->observe(port));take(f.model->set_rows({{.key="new-root",.label="Root"},{.key="new-branch",.label="Branch",.depth=1},{.key="new-leaf",.label="Leaf",.depth=2,.selected=true}}));check(events.size()==1&&events[0].data&&events[0].expansions==std::vector<lvrs::HierarchyExpansionChange>{{"new-branch",1,true},{"new-root",0,true}}&&events[0].state.active_key=="new-leaf"&&events[0].state.model_revision==take(f.model->state()).revision,"Source normalization lost ancestor transitions or published an old revision");}
void initial_key(){Fixture f;auto view=take(lvrs::HierarchyController::create(f.model,{.initial_active_key="leaf"}));check(take(view->state()).active_key=="leaf"&&take(view->expanded("branch"))&&take(f.view->state()).active_key=="root","An initial key did not seed an independent controller");auto missing=take(lvrs::HierarchyController::create(f.model,{.initial_active_key="absent"}));check(take(missing->state()).active_key=="root","A missing initial key did not use normal fallback selection");}
void disabled_expansion(){auto model=take(lvrs::HierarchyModel::create());take(model->set_rows({{.key="root",.label="Disabled root",.enabled=false},{.key="branch",.label="Branch",.depth=1},{.key="leaf",.label="Leaf",.depth=2},{.key="other",.label="Other"}}));auto view=take(lvrs::HierarchyController::create(model));const auto revision=take(model->state()).revision;check(take(view->activate_by_key("leaf"))&&take(view->expanded("root")),"Automatic expansion incorrectly treated a disabled ancestor as an ineligible target");take(view->collapse_all(false));check(!take(view->expanded("root"))&&take(view->state()).active_key=="other","Bulk collapse skipped a disabled branch or left a hidden selection");take(view->expand_all());check(take(view->expanded("root"))&&!take(view->toggle_expanded("root"))&&take(model->state()).revision==revision&&!take(model->row("root")).get().enabled,"Bulk expansion lost source behavior or enabled interactive toggling/data mutation");}

}
int main(int argc,char** argv){try{const std::string n=argc>1?argv[1]:"defaults";if(n=="defaults")defaults();else if(n=="activation")activation();else if(n=="hidden")hidden();else if(n=="keyboard")keyboard();else if(n=="collapse")collapse();else if(n=="independent")independent();else if(n=="updates")updates();else if(n=="selected")selected();else if(n=="force")force();else if(n=="extent")extent();else if(n=="drag")drag();else if(n=="readonly")readonly();else if(n=="stale")stale();else if(n=="observation")observation();else if(n=="errors")errors();else if(n=="close")close();else if(n=="source_close")source_close();else if(n=="ownership")ownership();else if(n=="default_extent")default_extent();else if(n=="cancel_notification")cancel_notification();else if(n=="pending_source")pending_source();else if(n=="close_in_notify")close_in_notify();else if(n=="expansion_batch")expansion_batch();else if(n=="ancestor_events")ancestor_events();else if(n=="expansion_source")expansion_source();else if(n=="initial_key")initial_key();else if(n=="disabled_expansion")disabled_expansion();else throw std::runtime_error("Unknown hierarchy controller case");std::cout<<"Native hierarchy controller "<<n<<" passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
